<template><view class="detail" :class="{article:isArticle}"><PageHeader :title="post?post.title+' - 乌鸦crow look':'作品详情'" back-button/><view v-if="post"><view v-if="isArticle" class="article-meta"><text class="article-title">{{post.title}}</text><view class="byline"><text class="category-link" @click="openCategory"><CrowIcon name="bars"/> {{post.category?.[0]?.name}}</text><text><CrowIcon name="underway-o"/> {{post.time}}</text><text><CrowIcon name="like-o"/> {{post.views||0}}</text></view></view><view v-else class="meta"><text @click="openCategory">{{post.category?.[0]?.name}}</text><text class="post-name">{{post.title}}</text><text><CrowIcon name="like-o"/> {{post.views||0}}</text></view><view class="content"><MediaVideo v-if="post.format==='video' && post.format_content?.video" class="film" :src="post.format_content.video" :poster="post.format_content.poster||post.thumbnail"/><template v-for="(block,i) in blocks" :key="i"><image v-if="block.type==='image'" class="photo" :src="block.src" mode="widthFix" :lazy-load="i>2" @click="preview(block.src)"/><video v-else-if="block.type==='video'" class="film" :src="block.src" controls/><rich-text v-else :nodes="block.html" class="prose"/></template></view><view v-if="!blocks.length" class="state">暂无内容</view><GuestPhotoExtras :post="post" :existing-images="blocks.filter(block => block.type==='image').map(block => block.src)"/><DetailAfterword :post="post" :is-article="isArticle" :liked="liked"/></view><view v-else class="state" @click="load">{{error||'加载中…'}}</view><view class="toolbar"><button class="consult" @click="service"><CrowIcon name="chat-o"/><text class="consult-label">咨询客服</text></button><button aria-label="评论" @click="comments"><CrowIcon name="comment-o"/><text v-if="post?.comment_count" class="badge">{{post.comment_count}}</text></button><button aria-label="点赞" @click="like"><CrowIcon :name="liked?'like':'like-o'"/></button><button aria-label="微信咨询" @click="service"><image src="/static/ui/wechat.svg"/></button><button aria-label="分享作品" @click="share"><image src="/static/ui/moments-outline.svg"/></button></view></view></template>
<script setup>
import {ref,computed} from 'vue';import {onLoad,onShow,onShareAppMessage} from '@dcloudio/uni-app';import {request,media,toggleFavorite,favorites,service,categoryById} from '../../lib/content';import PageHeader from '../../components/PageHeader.vue';import MediaVideo from '../../components/MediaVideo.vue';import DetailAfterword from '../../components/DetailAfterword.vue';import GuestPhotoExtras from '../../components/GuestPhotoExtras.vue';import CrowIcon from '../../components/CrowIcon.vue';
let id;const post=ref(null),error=ref(''),liked=ref(false);const sync=()=>liked.value=favorites().some(p=>p.id===Number(id));
const isArticle=computed(()=>!!categoryById(post.value?.category?.[0]?.id)?.pic_new);
const blocks=computed(()=>{const html=post.value?.content||'';let result=[],last=0;const re=/<img\b[^>]*\bsrc=["']([^"']+)["'][^>]*>|<video\b[^>]*>[\s\S]*?<\/video>/gi;let m;const addText=s=>{s=s.replace(/<\/?figure[^>]*>/g,'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/\son\w+=["'][^"']*["']/gi,'');if(s.replace(/<[^>]*>/g,'').trim())result.push({type:'text',html:s})};while((m=re.exec(html))){addText(html.slice(last,m.index));if(m[1])result.push({type:'image',src:media(m[1].replace(/&amp;/g,'&'))});else{const src=m[0].match(/src=["']([^"']+)/);if(src)result.push({type:'video',src:media(src[1])})}last=re.lastIndex}addText(html.slice(last));return result});
const preview=src=>uni.previewImage({urls:blocks.value.filter(x=>x.type==='image').map(x=>x.src),current:src});const load=async()=>{error.value='';try{post.value=(await request('post/get.json',{id},'post'+id)).post}catch(e){error.value=e.message}};
const like=()=>{if(post.value)liked.value=toggleFavorite(post.value)};const comments=()=>uni.navigateTo({url:'/pages/comments/comments?id='+id});const openCategory=()=>post.value?.category?.[0]&&uni.navigateTo({url:'/pages/articleList/articleList?category_id='+post.value.category[0].id});
const share=()=>uni.setClipboardData({data:post.value.title+' https://crow.richs.vip/'+id+'.htm'});onLoad(o=>{id=o.id;sync();load()});onShow(sync);onShareAppMessage(()=>({title:post.value?.title,path:'/pages/articleDetail/articleDetail?id='+id}))
</script>
<style scoped>.detail{padding-bottom:110rpx}.meta{position:relative;display:flex;align-items:center;justify-content:space-between;margin:30rpx 40rpx;gap:20rpx;font-size:12px;color:#999}.meta .post-name{font-size:12px;color:#111;position:absolute;left:50%;transform:translateX(-50%);font-weight:500}.content{margin:0 40rpx}.photo{width:100%;display:block;border-radius:10rpx;margin-bottom:40rpx}.film{width:100%;height:400rpx;margin-bottom:40rpx}.prose{font-size:28rpx;line-height:1.9;display:block;margin-bottom:24rpx;overflow-wrap:anywhere}.toolbar{height:90rpx;position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1rpx solid #eee;display:flex;align-items:center;gap:0;padding:12rpx 30rpx 12rpx 40rpx;padding-bottom:calc(12rpx + env(safe-area-inset-bottom));box-sizing:border-box;z-index:25}.toolbar button{position:relative;font-size:24px;color:#555;padding:0;background:transparent;line-height:1;display:flex;align-items:center;justify-content:center;flex:1}.toolbar image{height:40rpx;width:40rpx;filter:grayscale(1)}.toolbar .consult{flex:0 0 300rpx;margin-right:30rpx;border:1px solid #414d5a;border-radius:50rpx;height:70rpx;gap:20rpx;font-size:13px}.state{padding:100rpx 40rpx;text-align:center;color:#999;font-size:26rpx}.consult-label{border-left:2rpx solid #bbb;padding-left:20rpx;color:#888;line-height:1}.consult .crow-icon{font-size:22px}.badge{position:absolute;left:50%;top:-4rpx;background:#ff315c;color:white;font-size:9px;line-height:22rpx;min-width:20rpx;border-radius:5rpx}.article-meta{margin:50rpx 40rpx 60rpx}.article-title{font-size:20px;font-weight:500;line-height:1.6;display:block;margin-bottom:20rpx}.byline{display:flex;gap:28rpx;font-size:12px;color:#999;align-items:center}.category-link{color:#576b95}.article .photo{border-radius:0;margin:0}.article .content{margin-bottom:40rpx}</style>
